<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { api,errorText } from '../api'
import { allowed,date,display,listItems,kpiDisplayScore,canReadKpiScores } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import { useLoad } from '../composables'
import PageState from '../components/PageState.vue'
import StatusBadge from '../components/StatusBadge.vue'
import ActionDialog from '../components/ActionDialog.vue'
const auth=useAuth(),period=ref(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()).replace('/','-')),scores=ref<Row[]>([]),runs=ref<Row[]>([]),templates=ref<Row[]>([]),templateId=ref(''),simulation=ref(true),tab=ref(auth.me?.role==='ADMIN'?'runs':'scores'),operationError=ref(''),busy=ref(false),exporting=ref(false),exportFormat=ref('xlsx'),selected=ref<Row|null>(null),detailOpen=ref(false),dialog=ref(false),action=ref(''),row=ref<Row>({}),resource=ref(''),{loading,error,run}=useLoad()
const appeals=computed(()=>scores.value.flatMap(s=>(s.appeals??[]).map((a:Row)=>({...a,deptName:s.deptName,scoreId:s.id}))))
function load(){run(async()=>{const result=await Promise.allSettled([canReadKpiScores(auth.me?.role??'')?api.get('/kpi/scores',{period:period.value,companyId:auth.me?.companyId}):Promise.resolve([]),api.get('/kpi/runs'),api.get('/kpi/templates')]);if(result[0].status==='rejected')throw result[0].reason;return result},v=>{scores.value=listItems((v[0] as PromiseFulfilledResult<any>).value);if(v[1].status==='fulfilled')runs.value=listItems(v[1].value);if(v[2].status==='fulfilled')templates.value=listItems(v[2].value);const failures=v.slice(1).filter(x=>x.status==='rejected') as PromiseRejectedResult[];operationError.value=failures.map(x=>errorText(x.reason)).join('；')})}
function act(a:string,r:Row,res:string){action.value=a;row.value=r;resource.value=res;dialog.value=true}
async function calculate(){if(!templateId.value){operationError.value='请选择已登记的考核模板';return}if(!simulation.value&&templates.value.find(t=>t.id===templateId.value)?.simulationOnly){operationError.value='该候选模板仅支持模拟测算';return}busy.value=true;operationError.value='';try{await api.post('/admin/kpi/runs',{period:period.value,companyId:auth.me?.companyId,templateId:templateId.value,simulation:simulation.value});load()}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
async function exportFile(){exporting.value=true;operationError.value='';try{const params=new URLSearchParams({period:period.value,format:exportFormat.value});if(auth.me?.companyId)params.set('companyId',String(auth.me.companyId));await api.download('/kpi/export?'+params,`部门月度考核.${exportFormat.value}`)}catch(e){operationError.value=errorText(e)}finally{exporting.value=false}}
function metrics(s:Row):Row[]{let m=s.metrics??s.indicators??s.snapshot?.metrics??[];if(typeof m==='string'){try{m=JSON.parse(m)}catch{return []}}return Array.isArray(m)?m:Object.entries(m).map(([name,value])=>({name,...(typeof value==='object'&&value!==null?value:{value})}))}
onMounted(load)
</script>
<template><section class="page-heading"><div><p class="eyebrow">DEPARTMENT PERFORMANCE</p><h1>部门月度考核</h1><p class="muted">结果可复算，调整有依据，历史快照可追溯。</p></div><div v-if="canReadKpiScores(auth.me?.role??'')" class="action-strip"><el-select v-model="exportFormat" aria-label="导出格式" style="width:120px"><el-option label="Excel" value="xlsx"/><el-option label="PDF" value="pdf"/><el-option label="CSV" value="csv"/></el-select><el-button type="primary" plain :loading="exporting" @click="exportFile">导出考核结果</el-button></div></section><div class="policy-banner"><b>部门考核 · 个人考核默认关闭</b><span>沿用30 / 25 / 20 / 10 / 15权重 · 7天异议期 · 不直接用于薪资核算</span></div><el-alert v-if="operationError" :title="operationError" type="warning" :closable="false"/><section class="panel"><div class="filter-bar"><el-date-picker v-model="period" type="month" value-format="YYYY-MM" placeholder="选择考核月份" aria-label="考核月份"/><el-button type="primary" @click="load">查询</el-button><span class="muted">当前公司 {{ auth.me?.companyId }}</span></div><PageState :loading="loading" :error="error" @retry="load"><el-tabs v-model="tab"><el-tab-pane label="得分看板" name="scores"><el-empty v-if="!scores.length" description="当前月份暂无考核结果"/><div class="score-grid"><article v-for="s in scores" :key="s.id" class="score-card"><div class="row-between"><h2>{{ s.deptName||s.departmentName||s.deptId }}</h2><StatusBadge :status="s.status||(s.simulation?'SIMULATION':s.locked?'LOCKED':'OBJECTION')"/></div><div class="score-value">{{ kpiDisplayScore(s)==null?'N/A':kpiDisplayScore(s) }}<small v-if="kpiDisplayScore(s)!=null">/ 100</small></div><p class="muted">{{ s.period||period }} · 模板 {{ s.templateVersion||s.templateId||'—' }}</p><p class="muted">批次 {{ s.runId||s.batchId||'—' }} · {{ date(s.calculatedAt||s.createdAt) }}</p><div class="action-strip"><el-button size="small" @click="selected=s;detailOpen=true">指标明细</el-button><el-button v-if="allowed(s,'appeal')||allowed(s,'appeals')" size="small" @click="act('appeals',s,'kpi/scores')">提出申诉</el-button><el-button v-if="allowed(s,'adjust')" size="small" @click="act('adjust',s,'kpi/scores')">人工调分</el-button></div></article></div></el-tab-pane><el-tab-pane label="计算批次与模板" name="runs"><div v-if="auth.me?.role==='ADMIN'" class="calculation-form"><h2>新建计算批次</h2><p class="muted">候选模板仅用于模拟测算；正式模板变更需业务批准，模拟结果不会覆盖历史分数。</p><div class="filter-bar"><el-select v-model="templateId" placeholder="选择模板"><el-option v-for="t in templates" :key="t.id" :value="t.id" :label="`${t.name||t.id} · ${t.version||''}${t.simulationOnly?'（仅模拟）':''}`"/></el-select><el-checkbox v-model="simulation">模拟测算</el-checkbox><el-button type="primary" :loading="busy" @click="calculate">运行计算</el-button></div></div><el-empty v-if="!runs.length" description="暂无计算批次"/><article v-for="r in runs" :key="r.id" class="batch-row"><div><b>{{ r.period }} · 批次 {{ r.id }}</b><p class="muted">模板 {{ r.templateVersion||r.templateId }} · {{ date(r.createdAt) }} · {{ r.simulation?'模拟批次':'正式批次' }}</p></div><StatusBadge :status="r.status"/><el-button v-if="allowed(r,'unlock')" @click="act('unlock',r,'admin/kpi/runs')">解锁并留痕</el-button></article><h2>模板登记</h2><article v-for="t in templates" :key="t.id" class="template-row"><b>{{ t.name }} · v{{ t.version }}</b><p>{{ display(t.weights) }} · {{ t.simulationOnly?'候选模拟模板':'登记模板' }}</p><p class="muted">{{ t.description||t.formula }}</p></article></el-tab-pane><el-tab-pane label="申诉处理" name="appeals"><el-empty v-if="!appeals.length" description="当前结果暂无申诉记录"/><article v-for="a in appeals" :key="a.id" class="request-card"><div class="row-between"><b>{{ a.deptName||a.scoreId }}</b><StatusBadge :status="a.status"/></div><p class="pre-wrap">{{ a.reason }}</p><p class="muted">{{ date(a.createdAt) }} · {{ a.resolutionReason||a.decision||'待处理' }}</p><el-button v-if="allowed(a,'resolve')" @click="act('resolve',a,'kpi/appeals')">处理申诉</el-button></article></el-tab-pane></el-tabs></PageState></section><ActionDialog v-model="dialog" :row="row" :action="action" :resource="resource" @done="load"/><el-drawer v-model="detailOpen" title="指标明细与计算快照" size="640px"><template v-if="selected"><h2>{{ selected.deptName||selected.deptId }} · {{ selected.period||period }}</h2><p class="muted">模板版本 {{ selected.templateVersion||selected.templateId }} · 批次 {{ selected.runId||'—' }}</p><p v-if="!metrics(selected).length" class="notice">服务端未返回指标拆解。请联系管理员核对该批次快照。</p><article v-for="(m,i) in metrics(selected)" :key="i" class="metric-detail"><h3>{{ m.name||m.label||'指标 '+(i+1) }}</h3><p>原始值 {{ display(m.rawValue??m.value) }} · 指标分 {{ display(m.score) }} · 权重 {{ display(m.weight) }}</p><p class="muted">{{ m.formula||m.explanation||m.reason }}</p></article><h3>调整与历史</h3><el-empty v-if="!selected.adjustments?.length&&!selected.history?.length" description="未返回调整记录" :image-size="60"/><article v-for="(h,i) in selected.adjustments||selected.history||[]" :key="i" class="request-card"><b>{{ display(h.oldScore) }} → {{ display(h.newScore??h.score) }}</b><p>{{ h.reason }}</p><small>{{ date(h.createdAt) }} · {{ h.operatorName||h.actorName }}</small></article><p class="scope-note">N/A表示不适用，不自动按0分或100分处理。冻结批次保留原始分母、模板与计算结果。</p></template></el-drawer></template>
